def max_value_on_paths(N: int, grid_values: list[tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each cell value can be collected at most once, even if both paths pass through it.
    Paths start at (1,1) and end at (N,N), moving only right or down.
    """
    # Build grid with 1-indexing
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # DP over steps k = i1 + j1 = i2 + j2
    # dp[i1][i2] = max sum for current step
    neg_inf = -10**18
    dp_prev = [[neg_inf] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]  # start cell value counted once

    for k in range(2, 2 * N + 1):
        dp_cur = [[neg_inf] * (N + 1) for _ in range(N + 1)]
        for i1 in range(1, N + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(1, N + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                # Value collected at this step
                val = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    val += grid[i2][j2]
                # Best previous state
                best = neg_inf
                for pi1, pi2 in ((i1 - 1, i2 - 1), (i1 - 1, i2), (i1, i2 - 1), (i1, i2)):
                    if pi1 >= 1 and pi2 >= 1:
                        best = max(best, dp_prev[pi1][pi2])
                if best != neg_inf:
                    dp_cur[i1][i2] = best + val
        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] != neg_inf else 0

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    Parameters:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    # Ensure mapping covers all 26 letters and is bijective
    if len(mapping) != 26:
        return "Failed"
    if set(mapping.values()) != set('ABCDEFGHIJKLMNOPQRSTUVWXYZ'):
        return "Failed"

    try:
        decoded = ''.join(mapping[ch] for ch in message)
    except KeyError:
        return "Failed"

    return decoded

